-- --- Payload guard ----------------------------------------------------------
DO $$
DECLARE v_n int; v_dup int; v_bad text;
BEGIN
  SELECT count(*) INTO v_n FROM mb_seed;
  IF v_n <> 10 THEN RAISE EXCEPTION 'macon-bibb people payload: expected 10 rows, got %', v_n; END IF;

  SELECT count(*) INTO v_dup FROM (SELECT ext_id FROM mb_seed GROUP BY ext_id HAVING count(*) > 1) x;
  IF v_dup <> 0 THEN RAISE EXCEPTION 'macon-bibb people payload: % duplicate external_id(s)', v_dup; END IF;

  SELECT count(*) INTO v_n FROM mb_seed WHERE ext_id NOT BETWEEN -1331050 AND -1331036;
  IF v_n <> 0 THEN RAISE EXCEPTION 'macon-bibb people payload: % out-of-band external_id(s)', v_n; END IF;

  -- Every (geo_id, mtfcc, district_type, title) is a single seat in this wave.
  SELECT count(*) INTO v_dup FROM (
    SELECT geo_id, mtfcc, district_type, office_title FROM mb_seed
    GROUP BY geo_id, mtfcc, district_type, office_title HAVING count(*) > 1
  ) x;
  IF v_dup <> 0 THEN RAISE EXCEPTION 'macon-bibb people payload: % duplicate seat key(s)', v_dup; END IF;

  -- 🔴 A DATE AND ITS PRECISION MUST AGREE IN BOTH DIRECTIONS.
  SELECT count(*) INTO v_n FROM mb_seed WHERE term_start IS NULL AND start_precision <> 'unknown';
  IF v_n <> 0 THEN RAISE EXCEPTION 'macon-bibb people payload: % row(s) have no term_start but claim a precision', v_n; END IF;
  SELECT count(*) INTO v_n FROM mb_seed WHERE term_start IS NOT NULL AND start_precision = 'unknown';
  IF v_n <> 0 THEN RAISE EXCEPTION 'macon-bibb people payload: % row(s) carry a term_start but declare it unknown', v_n; END IF;

  -- 🔴🔴 THE EXACT TUPLE SET, NOT A COUNT. This is the guard that refuses the
  -- single most likely corruption of this wave: giving all ten people the
  -- county's published 2025-01-01, which is right for exactly two of them.
  -- A count of dated rows cannot see a date that MOVED.
  SELECT count(*), string_agg(format('%s->%s/%s/%s', s.ext_id, s.term_start, s.start_precision, s.how_started), ', ' ORDER BY s.ext_id)
    INTO v_n, v_bad
    FROM mb_seed s
   WHERE NOT EXISTS (
     SELECT 1 FROM (VALUES
    (-1331036, DATE '2021-01-01', 'day', 'elected'),
    (-1331037, DATE '2018-06-01', 'month', 'elected'),
    (-1331038, DATE '2021-01-01', 'day', 'elected'),
    (-1331039, DATE '2024-10-15', 'day', 'appointed'),
    (-1331040, DATE '2025-01-01', 'day', 'elected'),
    (-1331041, DATE '2026-04-20', 'day', 'elected'),
    (-1331042, DATE '2021-01-01', 'day', 'elected'),
    (-1331043, DATE '2021-01-01', 'day', 'elected'),
    (-1331044, DATE '2025-01-01', 'day', 'elected'),
    (-1331045, DATE '2024-01-17', 'day', 'appointed')
     ) AS e(ext_id, term_start, start_precision, how_started)
      WHERE e.ext_id = s.ext_id
        AND e.term_start IS NOT DISTINCT FROM s.term_start
        AND e.start_precision = s.start_precision
        AND e.how_started = s.how_started
   );
  IF v_n <> 0 THEN
    RAISE EXCEPTION 'macon-bibb people payload: % row(s) do not match the sourced (id, term_start, precision, how_started) tuple: %', v_n, v_bad;
  END IF;

  -- 🔴 EXACTLY 2 ROWS ARE 'appointed', AND THEY ARE Stewart AND Bailey.
  -- Charter Sec. 15(b): the Commission may appoint only when the vacancy falls
  -- within 12 months of the term's expiry. Everyone else was elected.
  SELECT count(*) INTO v_n FROM mb_seed WHERE how_started = 'appointed';
  IF v_n <> 2 THEN RAISE EXCEPTION 'macon-bibb people payload: expected 2 appointed row(s), got %', v_n; END IF;
  SELECT count(*) INTO v_n FROM mb_seed
   WHERE how_started = 'appointed' AND ext_id NOT IN (-1331045, -1331039);
  IF v_n <> 0 THEN RAISE EXCEPTION 'macon-bibb people payload: % appointed row(s) are not the expected two', v_n; END IF;

  -- 🔴 how_started IS A CHECKED ENUM. 'special election' is not in it, and Wynn
  -- and Cooke both won specials.
  SELECT count(*) INTO v_n FROM mb_seed
   WHERE how_started NOT IN ('elected','appointed','succeeded','redistricted','unknown');
  IF v_n <> 0 THEN RAISE EXCEPTION 'macon-bibb people payload: % row(s) carry a how_started the CHECK will refuse', v_n; END IF;

  -- 🔴 EXACTLY ONE ROW IS 'month' PRECISION, AND IT IS WYNN. Everything else is
  -- 'day'. A wave that "tidied" her to a day would be inventing an oath date.
  SELECT count(*) INTO v_n FROM mb_seed WHERE start_precision = 'month';
  IF v_n <> 1 THEN RAISE EXCEPTION 'macon-bibb people payload: expected exactly 1 month-precision row (Wynn), got %', v_n; END IF;

  -- ⚠ alternate_names is NOT NULL DEFAULT '{}'. Emit an empty array, never NULL.
  SELECT count(*) INTO v_n FROM mb_seed WHERE aliases IS NULL;
  IF v_n <> 0 THEN RAISE EXCEPTION 'macon-bibb people payload: % row(s) carry a NULL aliases array', v_n; END IF;

  -- And every seat named must resolve to exactly one office in prod.
  SELECT count(*) INTO v_n FROM mb_seed s
   WHERE (SELECT count(*) FROM essentials.offices o
            JOIN essentials.districts d ON d.id = o.district_id
           WHERE d.geo_id = s.geo_id AND d.mtfcc = s.mtfcc
             AND d.district_type = s.district_type AND lower(d.state) = 'ga'
             AND o.title = s.office_title) <> 1;
  IF v_n <> 0 THEN RAISE EXCEPTION 'macon-bibb people payload: % seat(s) do not resolve to exactly one office -- run the structure half first', v_n; END IF;
END $$;

-- --- Politicians ------------------------------------------------------------
INSERT INTO essentials.politicians
  (external_id, full_name, first_name, last_name, middle_initial, name_suffix,
   alternate_names, is_incumbent, is_active, data_source)
SELECT s.ext_id, s.full_name, s.first_name, s.last_name,
       nullif(s.middle_initial, ''), nullif(s.name_suffix, ''),
       s.aliases, true, true, s.source
FROM mb_seed s
ON CONFLICT (external_id) DO NOTHING;

-- --- Occupancy --------------------------------------------------------------
-- 🔴 ONE PATH: essentials.seat_officeholder(), for all 10. Every person here
-- carries a real term_start, so the helper's refusal of NULL never fires and
-- nothing is hand-rolled. GA-4 had to direct-insert nine of eleven because
-- Columbus publishes no service-start at all; Macon-Bibb does.
--
-- ⚠ THE REFUSAL BRANCH IS KEPT ON PURPOSE. It is unreachable in this migration
--   (the payload guard above proves 0 undated rows), and it exists so that
--   editing the roster to add an undated person cannot silently bypass the
--   helper. An undated open-ended term is a legitimate record -- the ADR 0002
--   phase-2 backfill wrote 81,676 of them -- but it must be a decision, not a
--   side effect.
DO $$
DECLARE r record; v_seated int := 0; v_blank int := 0; v_prior int;
BEGIN
  FOR r IN
    SELECT s.term_start, s.start_precision, s.how_started, s.source,
           o.id AS office_id, p.id AS politician_id
      FROM mb_seed s
      JOIN essentials.districts d
        ON d.geo_id = s.geo_id AND d.mtfcc = s.mtfcc
       AND d.district_type = s.district_type AND lower(d.state) = 'ga'
      JOIN essentials.offices o ON o.district_id = d.id AND o.title = s.office_title
      JOIN essentials.politicians p ON p.external_id = s.ext_id
     WHERE NOT EXISTS (
       SELECT 1 FROM essentials.office_terms t
        WHERE t.office_id = o.id AND t.politician_id = p.id
     )
  LOOP
    IF r.term_start IS NOT NULL THEN
      PERFORM essentials.seat_officeholder(
        r.office_id, r.politician_id, r.term_start, r.source, r.how_started, r.start_precision
      );
      v_seated := v_seated + 1;
    ELSE
      IF r.start_precision <> 'unknown' THEN
        RAISE EXCEPTION 'macon-bibb people: office % has no term_start but claims precision % -- refusing', r.office_id, r.start_precision;
      END IF;
      SELECT count(*) INTO v_prior FROM essentials.office_terms t WHERE t.office_id = r.office_id;
      IF v_prior <> 0 THEN
        RAISE EXCEPTION 'macon-bibb people: office % already carries % term row(s), so an undated open term cannot be inserted directly -- close the predecessor and give this person a real date', r.office_id, v_prior;
      END IF;
      INSERT INTO essentials.office_terms
        (office_id, politician_id, term_start, term_end, start_precision, how_started, source)
      VALUES (r.office_id, r.politician_id, NULL, NULL, 'unknown', r.how_started, r.source);
      v_blank := v_blank + 1;
    END IF;
  END LOOP;
  RAISE NOTICE 'macon-bibb people: seated % official(s) via seat_officeholder(), % with an honest unknown start', v_seated, v_blank;
END $$;

-- --- Post-verify gate ------------------------------------------------------
-- 🔴 SCOPED TO THE TWO CITY CHAMBERS, NEVER TO THE GOVERNMENT. Macon-Bibb is
-- consolidated: Task 4's five county officers join this SAME government row, so
-- a government-wide seat count would pass today and fail forever afterwards.
DO $$
DECLARE v_gov uuid; v_n int; v_d text;
BEGIN
  SELECT id INTO v_gov FROM essentials.governments
   WHERE geo_id = '1349008' AND type = 'City';
  IF v_gov IS NULL THEN RAISE EXCEPTION 'macon-bibb people: the government row is missing -- apply the structure half first'; END IF;

  -- ⚠ COUNT THIS MIGRATION'S OWN IDS, NOT THE WHOLE BAND. Counting the band is
  -- what made CC_0009 non-idempotent once CC_0010 added its eleven.
  SELECT count(*) INTO v_n FROM essentials.politicians
   WHERE external_id IN (-1331045, -1331044, -1331043, -1331042, -1331041, -1331040, -1331039, -1331038, -1331037, -1331036);
  IF v_n <> 10 THEN RAISE EXCEPTION 'macon-bibb people: expected 10 of this migration''s politicians, got %', v_n; END IF;

  -- 🔴 count(och.politician_id), NOT count(*): office_current_holder LEFT JOINs
  -- from offices, so a vacancy is a NULL politician_id, never an absent row, and
  -- count(*) would pass VACUOUSLY on an entirely empty government.
  SELECT count(och.politician_id) INTO v_n
    FROM essentials.offices o
    JOIN essentials.chambers c ON c.id = o.chamber_id
    LEFT JOIN essentials.office_current_holder och ON och.office_id = o.id
   WHERE c.government_id = v_gov AND c.name IN ('Macon-Bibb County Commission', 'Office of the Mayor');
  IF v_n <> 10 THEN RAISE EXCEPTION 'macon-bibb people: expected 10 seated city officials, found %', v_n; END IF;

  SELECT count(*) INTO v_n FROM essentials.offices o
    JOIN essentials.chambers c ON c.id = o.chamber_id
   WHERE c.government_id = v_gov AND c.name IN ('Macon-Bibb County Commission', 'Office of the Mayor') AND o.is_vacant = true;
  IF v_n <> 0 THEN RAISE EXCEPTION 'macon-bibb people: % city office(s) flagged vacant, expected 0', v_n; END IF;

  -- One seated member per numbered district, counted PER DISTRICT. A single
  -- total can hide two holders on one district and none on another.
  FOR v_d IN SELECT 'macon-bibb-ga-commission-district-' || gs FROM generate_series(1,9) gs LOOP
    SELECT count(och.politician_id) INTO v_n
      FROM essentials.districts d
      JOIN essentials.offices o ON o.district_id = d.id
      LEFT JOIN essentials.office_current_holder och ON och.office_id = o.id
     WHERE d.geo_id = v_d AND d.mtfcc = 'X0045' AND d.district_type = 'LOCAL';
    IF v_n <> 1 THEN RAISE EXCEPTION 'macon-bibb people: district % has % holder(s), expected exactly 1', v_d, v_n; END IF;
  END LOOP;

  -- 🔴 EXACTLY 1 HOLDER ON THE CITYWIDE DISTRICT: the Mayor. Columbus expects
  -- THREE here -- its Mayor plus at-large Posts 9 and 10 -- and Macon-Bibb has no
  -- at-large seats at all, so three would mean two commissioners had been seated
  -- on the wrong district.
  SELECT count(och.politician_id) INTO v_n
    FROM essentials.districts d
    JOIN essentials.offices o ON o.district_id = d.id
    JOIN essentials.chambers c ON c.id = o.chamber_id
    LEFT JOIN essentials.office_current_holder och ON och.office_id = o.id
   WHERE c.government_id = v_gov AND c.name IN ('Macon-Bibb County Commission', 'Office of the Mayor')
     AND d.geo_id = '1349008' AND d.mtfcc = 'G4110' AND d.district_type = 'LOCAL';
  IF v_n <> 1 THEN RAISE EXCEPTION 'macon-bibb people: expected 1 holder(s) on Macon-Bibb Citywide, got %', v_n; END IF;

  -- 🔴 NOT ONE OF THESE TERMS CARRIES A term_end. A future term_end makes a seat
  -- silently self-vacate on a date nobody watches (spec §4.1).
  SELECT count(*) INTO v_n
    FROM essentials.office_terms t
    JOIN essentials.politicians p ON p.id = t.politician_id
   WHERE p.external_id IN (-1331045, -1331044, -1331043, -1331042, -1331041, -1331040, -1331039, -1331038, -1331037, -1331036) AND t.term_end IS NOT NULL;
  IF v_n <> 0 THEN RAISE EXCEPTION 'macon-bibb people: % term row(s) carry a term_end -- none may', v_n; END IF;

  -- 🔴 AND EACH DATED ROW CARRIES EXACTLY THE DATE THAT WAS SOURCED, asserted
  -- INDIVIDUALLY by external_id. A count of "how many are dated" cannot see a
  -- date that moved, and the value most likely to be substituted here is
  -- 2025-01-01 for everyone -- the county's own published sentence, which is
  -- right for exactly two of the ten.
  SELECT count(*) INTO v_n
    FROM essentials.office_terms t
    JOIN essentials.politicians p ON p.id = t.politician_id
   WHERE p.external_id = -1331036
     AND t.term_start = DATE '2021-01-01'
     AND t.start_precision = 'day'
     AND t.how_started = 'elected'
     AND t.term_end IS NULL;
  IF v_n <> 1 THEN RAISE EXCEPTION 'macon-bibb people: Lester Miller (-1331036) does not hold exactly one OPEN term starting 2021-01-01 at day precision, how_started elected; got %', v_n; END IF;

  SELECT count(*) INTO v_n
    FROM essentials.office_terms t
    JOIN essentials.politicians p ON p.id = t.politician_id
   WHERE p.external_id = -1331037
     AND t.term_start = DATE '2018-06-01'
     AND t.start_precision = 'month'
     AND t.how_started = 'elected'
     AND t.term_end IS NULL;
  IF v_n <> 1 THEN RAISE EXCEPTION 'macon-bibb people: Valerie Wynn (-1331037) does not hold exactly one OPEN term starting 2018-06-01 at month precision, how_started elected; got %', v_n; END IF;

  SELECT count(*) INTO v_n
    FROM essentials.office_terms t
    JOIN essentials.politicians p ON p.id = t.politician_id
   WHERE p.external_id = -1331038
     AND t.term_start = DATE '2021-01-01'
     AND t.start_precision = 'day'
     AND t.how_started = 'elected'
     AND t.term_end IS NULL;
  IF v_n <> 1 THEN RAISE EXCEPTION 'macon-bibb people: Paul Bronson (-1331038) does not hold exactly one OPEN term starting 2021-01-01 at day precision, how_started elected; got %', v_n; END IF;

  SELECT count(*) INTO v_n
    FROM essentials.office_terms t
    JOIN essentials.politicians p ON p.id = t.politician_id
   WHERE p.external_id = -1331039
     AND t.term_start = DATE '2024-10-15'
     AND t.start_precision = 'day'
     AND t.how_started = 'appointed'
     AND t.term_end IS NULL;
  IF v_n <> 1 THEN RAISE EXCEPTION 'macon-bibb people: Stanley Stewart (-1331039) does not hold exactly one OPEN term starting 2024-10-15 at day precision, how_started appointed; got %', v_n; END IF;

  SELECT count(*) INTO v_n
    FROM essentials.office_terms t
    JOIN essentials.politicians p ON p.id = t.politician_id
   WHERE p.external_id = -1331040
     AND t.term_start = DATE '2025-01-01'
     AND t.start_precision = 'day'
     AND t.how_started = 'elected'
     AND t.term_end IS NULL;
  IF v_n <> 1 THEN RAISE EXCEPTION 'macon-bibb people: Joey Hulett (-1331040) does not hold exactly one OPEN term starting 2025-01-01 at day precision, how_started elected; got %', v_n; END IF;

  SELECT count(*) INTO v_n
    FROM essentials.office_terms t
    JOIN essentials.politicians p ON p.id = t.politician_id
   WHERE p.external_id = -1331041
     AND t.term_start = DATE '2026-04-20'
     AND t.start_precision = 'day'
     AND t.how_started = 'elected'
     AND t.term_end IS NULL;
  IF v_n <> 1 THEN RAISE EXCEPTION 'macon-bibb people: Andrea Cooke (-1331041) does not hold exactly one OPEN term starting 2026-04-20 at day precision, how_started elected; got %', v_n; END IF;

  SELECT count(*) INTO v_n
    FROM essentials.office_terms t
    JOIN essentials.politicians p ON p.id = t.politician_id
   WHERE p.external_id = -1331042
     AND t.term_start = DATE '2021-01-01'
     AND t.start_precision = 'day'
     AND t.how_started = 'elected'
     AND t.term_end IS NULL;
  IF v_n <> 1 THEN RAISE EXCEPTION 'macon-bibb people: Raymond Wilder (-1331042) does not hold exactly one OPEN term starting 2021-01-01 at day precision, how_started elected; got %', v_n; END IF;

  SELECT count(*) INTO v_n
    FROM essentials.office_terms t
    JOIN essentials.politicians p ON p.id = t.politician_id
   WHERE p.external_id = -1331043
     AND t.term_start = DATE '2021-01-01'
     AND t.start_precision = 'day'
     AND t.how_started = 'elected'
     AND t.term_end IS NULL;
  IF v_n <> 1 THEN RAISE EXCEPTION 'macon-bibb people: Bill Howell (-1331043) does not hold exactly one OPEN term starting 2021-01-01 at day precision, how_started elected; got %', v_n; END IF;

  SELECT count(*) INTO v_n
    FROM essentials.office_terms t
    JOIN essentials.politicians p ON p.id = t.politician_id
   WHERE p.external_id = -1331044
     AND t.term_start = DATE '2025-01-01'
     AND t.start_precision = 'day'
     AND t.how_started = 'elected'
     AND t.term_end IS NULL;
  IF v_n <> 1 THEN RAISE EXCEPTION 'macon-bibb people: Donice Bryant (-1331044) does not hold exactly one OPEN term starting 2025-01-01 at day precision, how_started elected; got %', v_n; END IF;

  SELECT count(*) INTO v_n
    FROM essentials.office_terms t
    JOIN essentials.politicians p ON p.id = t.politician_id
   WHERE p.external_id = -1331045
     AND t.term_start = DATE '2024-01-17'
     AND t.start_precision = 'day'
     AND t.how_started = 'appointed'
     AND t.term_end IS NULL;
  IF v_n <> 1 THEN RAISE EXCEPTION 'macon-bibb people: Brendalyn Bailey (-1331045) does not hold exactly one OPEN term starting 2024-01-17 at day precision, how_started appointed; got %', v_n; END IF;

  -- No city office may be left with no term row at all: that is the
  -- invisible-office failure, and nothing else errors.
  SELECT count(*) INTO v_n FROM essentials.offices o
    JOIN essentials.chambers c ON c.id = o.chamber_id
   WHERE c.government_id = v_gov AND c.name IN ('Macon-Bibb County Commission', 'Office of the Mayor')
     AND NOT EXISTS (SELECT 1 FROM essentials.office_terms t WHERE t.office_id = o.id);
  IF v_n <> 0 THEN RAISE EXCEPTION 'macon-bibb people: % city office(s) carry no office_terms row and are invisible', v_n; END IF;

  RAISE NOTICE 'macon-bibb people OK: 10 politicians, 10 seated across 10 city offices, 0 vacancies (9 day, 1 month, 2 appointed), all via seat_officeholder()';
END $$;

COMMIT;
